import{categories,products,money,fa,sanitizeCart,cartTotals,selectProducts}from'./catalog.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icons={home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',pen:'<path d="m4 20 2-6L17 3l4 4L10 18l-6 2Z M14 6l4 4 M6 14l4 4"/>',pencil:'<path d="m3 21 2-7L17 2l5 5-12 12-7 2Z M14 5l5 5 M5 14l5 5 M8 16 18 6"/>',book:'<rect x="5" y="3" width="15" height="19" rx="2"/><path d="M8 3v19M2 7h5M2 12h5M2 17h5M12 8h5M12 12h4"/>',palette:'<path d="M21 12A9 9 0 1 0 12 21c4 0 1-4 4-5s5-1 5-4Z"/><circle cx="8" cy="7" r="1"/><circle cx="14" cy="6" r="1"/><circle cx="6" cy="12" r="1"/><circle cx="8" cy="17" r="1"/>',glue:'<rect x="7" y="9" width="10" height="13" rx="2"/><path d="M9 9V5h6v4M11 5V2h2v3M7 14h10"/>',case:'<rect x="3" y="8" width="18" height="13" rx="3"/><path d="M8 8V5a4 4 0 0 1 8 0v3M3 13h18M10 13v3h4v-3"/>',clip:'<path d="M9 8v10a3 3 0 0 0 6 0V6a5 5 0 0 0-10 0v12a7 7 0 0 0 14 0V7"/>',paper:'<path d="M5 2h10l5 5v15H5Z M15 2v6h5M9 12h7M9 16h7"/>',ruler:'<path d="m3 17 14-14 5 5L8 22ZM8 12l3 3M12 8l3 3M16 4l3 3"/>',gift:'<rect x="3" y="8" width="18" height="5" rx="1"/><path d="M5 13v9h14v-9M12 8v14M12 8C2 8 5-2 10 4l2 4ZM12 8c10 0 7-10 2-4l-2 4Z"/>'};
function icon(k){return`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.pen}</svg>`;}
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let cart=sanitizeCart(read('behjat-cart-v1',{}));let rawFavorites=read('behjat-favorites-v1',[]);let favorites=Array.isArray(rawFavorites)?rawFavorites.filter(id=>products.some(p=>p.id===id)):[];let current='home',favoriteView=false,searchTerm='',lastFocused=null;
function persist(){try{localStorage.setItem('behjat-cart-v1',JSON.stringify(cart));localStorage.setItem('behjat-favorites-v1',JSON.stringify(favorites));}catch{toast('ذخیره روی این دستگاه ممکن نیست؛ سبد تا زمان بستن صفحه حفظ می‌شود.');}}
function art(p,extra=''){const pen=p.category==='pens';return`<div class="product-art ${pen?'pen-display':''} ${extra}" role="img" aria-label="تصویر نمونهٔ ${p.name}" style="--px:${pen?(p.variant%4)*100/3:(p.art%3)*50}%;--py:${pen?Math.floor(p.variant/4)*50:Math.floor(p.art/3)*50}%"></div>`;}
$('#categories').innerHTML=categories.map(c=>`<button class="category-button" data-category="${c.id}"${c.id==='home'?' aria-current="page"':''}><span class="category-icon">${icon(c.icon)}</span>${c.name}</button>`).join('');
function recommend(){const picks=['pencils-1','cases-1','pens-6','notebooks-1'];$('#recommend-grid').innerHTML=picks.map(id=>{const p=products.find(p=>p.id===id);return`<article class="recommend-card"><button class="recommend-detail" data-detail="${p.id}" aria-label="جزئیات ${p.name}">${art(p)}<h3>${p.name}</h3></button><div class="recommend-price"><span>${money(p.price)}</span><button class="quick-add" data-add="${p.id}" aria-label="افزودن ${p.name} به سبد">+</button></div></article>`;}).join('');}
function openCategory(id,{fromHash=false,keepSearch=false}={}){if(!categories.some(c=>c.id===id)&&!['all','favorites'].includes(id))id='home';favoriteView=id==='favorites';current=id;if(!keepSearch){searchTerm='';$('#search').value='';}if(!fromHash){const hash=id==='home'?'#home':`#shelf=${id}`;if(location.hash!==hash)history.pushState(null,'',hash);}$('#favorites').setAttribute('aria-pressed',favoriteView);$$('.category-button').forEach(b=>{b.classList.toggle('active',b.dataset.category===id);if(b.dataset.category===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#room').hidden=id!=='home';$('#shelf').hidden=id==='home';if(id!=='home'){renderShelf();$('.shelf-scroll').scrollTop=0;$('#shelf').classList.remove('shelf-enter');void $('#shelf').offsetWidth;$('#shelf').classList.add('shelf-enter');}document.title=id==='home'?'فروشگاه خیال | دکّان بهجت':`${titleForView()} | دکّان بهجت`;}
function titleForView(){if(searchTerm)return'پیدا کن، دوستش داشته باش';if(current==='favorites')return'دوست‌داشتنی‌های تو';if(current==='all')return'همهٔ رنگ‌های دکّان';return categories.find(c=>c.id===current)?.name||'قفسه‌های دکّان';}
function renderShelf(){const category=['favorites','all','home'].includes(current)?'all':current;const list=selectProducts({category,query:searchTerm,favorites:favoriteView?favorites:null,sort:$('#sort').value});$('#shelf-title').textContent=titleForView();$('#shelf-subtitle').textContent=searchTerm?`نتیجهٔ جستجوی «${searchTerm}»`:categories.find(c=>c.id===current)?.subtitle||'چیزهای کوچکی که روزت را قشنگ‌تر می‌کنند';$('#result-count').textContent=fa(list.length)+' انتخاب';$('#breadcrumb-title').textContent=titleForView();$('#product-grid').innerHTML=list.map((p,i)=>`<article class="shelf-product" style="--delay:${Math.min(i,11)*.035}s"><button class="favorite-product" data-favorite="${p.id}" aria-label="علاقه‌مندی ${p.name}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'♥':'♡'}</button><button class="product-open" data-detail="${p.id}" aria-label="جزئیات ${p.name}">${art(p)}</button><div class="product-nameplate"><h2>${p.name}</h2><span>${money(p.price)}</span></div><button class="shelf-add" data-add="${p.id}" aria-label="افزودن ${p.name} به سبد"><span>افزودن به سبد</span><b>+</b></button></article>`).join('');$('#empty-results').hidden=list.length>0;if(favoriteView&&!list.length){$('#empty-results h2').textContent='هنوز دلت پیش چیزی نرفته؟';$('#empty-results p').textContent='روی قلب کنار محصول بزن تا اینجا نگهش داریم.';}else{$('#empty-results h2').textContent='این گوشه هنوز پیداش نکردیم!';$('#empty-results p').textContent='یک اسم دیگه جستجو کن یا همهٔ قفسه‌ها رو ببین.';}}
function updateCart(){const {count,total}=cartTotals(cart);$$('.cart-count').forEach(el=>el.textContent=fa(count));$('#basket-total').textContent=count?money(total):'سبدت منتظر رنگ‌هاست';$('#cart-total').textContent=money(total);$('#cart-empty').hidden=count>0;$('.cart-summary').hidden=count===0;$('#cart-items').innerHTML=Object.entries(cart).map(([id,q])=>{const p=products.find(p=>p.id===id);return`<article class="cart-row">${art(p)}<div><h3>${p.name}</h3><p class="row-price">${money(p.price*q)}</p><div class="quantity-row"><div class="quantity"><button data-quantity="${id}" data-delta="1" aria-label="افزایش تعداد ${p.name}" ${q>=99?'disabled':''}>+</button><span aria-label="تعداد">${fa(q)}</span><button data-quantity="${id}" data-delta="-1" aria-label="کاهش تعداد ${p.name}">−</button></div><button class="remove-item" data-remove="${id}" aria-label="حذف ${p.name}">حذف</button></div></div></article>`;}).join('');}
function addToCart(id,source){const p=products.find(p=>p.id===id);if(!p)throw Error('Unknown product');if((cart[id]||0)>=99){toast('برای هر محصول تا ۹۹ عدد می‌توانی انتخاب کنی.');return{added:false};}cart[id]=(cart[id]||0)+1;persist();updateCart();toast(`${p.name} به سبدت اضافه شد ♡`);if(source){const target=$('.basket-pill').getBoundingClientRect(),r=source.getBoundingClientRect();if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const spark=document.createElement('span');spark.className='fly-spark';spark.textContent='✦';spark.style.left=r.left+r.width/2+'px';spark.style.top=r.top+r.height/2+'px';spark.style.setProperty('--dx',`${target.left+target.width/2-r.left-r.width/2}px`);spark.style.setProperty('--dy',`${target.top+target.height/2-r.top-r.height/2}px`);document.body.append(spark);setTimeout(()=>spark.remove(),800);}source.classList.add('added');const oldLabel=source.innerHTML;source.innerHTML=source.classList.contains('quick-add')?'✓':'اضافه شد ✓';setTimeout(()=>{source.innerHTML=oldLabel;source.classList.remove('added');},1000);}$('.basket-pill').classList.remove('bump');void $('.basket-pill').offsetWidth;$('.basket-pill').classList.add('bump');return{added:true,...cartTotals(cart)};}
function changeQuantity(id,delta){if(!cart[id])return;cart[id]=Math.min(99,cart[id]+delta);if(cart[id]<=0)delete cart[id];persist();updateCart();}
function showDialog(selector){lastFocused=document.activeElement;$(selector).showModal();}
function details(id){const p=products.find(p=>p.id===id);if(!p)return;$('#detail-content').innerHTML=`<div class="detail-art">${art(p)}</div><div class="detail-info"><span class="detail-category">${categories.find(c=>c.id===p.category).name}</span><h2 id="detail-title">${p.name}</h2><p>${p.description}</p><strong class="detail-price">${money(p.price)}</strong><button class="detail-add" data-add="${p.id}">افزودن به سبد +</button><small>تصویر، قیمت و محصول نمونه هستند. مشخصات نهایی پس از اتصال کاتالوگ واقعی درج می‌شوند.</small></div>`;showDialog('#product-dialog');}
document.addEventListener('click',e=>{const category=e.target.closest('[data-category]');if(category){openCategory(category.dataset.category);return;}const add=e.target.closest('[data-add]');if(add){addToCart(add.dataset.add,add);return;}const detail=e.target.closest('[data-detail]');if(detail){details(detail.dataset.detail);return;}const fav=e.target.closest('[data-favorite]');if(fav){const id=fav.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persist();if(favoriteView)renderShelf();else{fav.setAttribute('aria-pressed',favorites.includes(id));fav.textContent=favorites.includes(id)?'♥':'♡';}return;}const q=e.target.closest('[data-quantity]');if(q){changeQuantity(q.dataset.quantity,Number(q.dataset.delta));return;}const remove=e.target.closest('[data-remove]');if(remove){delete cart[remove.dataset.remove];persist();updateCart();return;}if(e.target.closest('.cart-open'))showDialog('#cart-dialog');if(e.target.closest('.close-dialog,.continue-shopping'))e.target.closest('dialog')?.close();});
$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});d.addEventListener('close',()=>lastFocused?.focus());});
$('#back-room').addEventListener('click',()=>openCategory('home'));$('#favorites').addEventListener('click',()=>openCategory(favoriteView?'home':'favorites'));$('#sort').addEventListener('change',renderShelf);let searchTimer;$('#search').addEventListener('input',e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{searchTerm=e.target.value.trim().slice(0,100);openCategory('all',{keepSearch:true});},180);});$('.search').addEventListener('submit',e=>{e.preventDefault();clearTimeout(searchTimer);searchTerm=$('#search').value.trim().slice(0,100);openCategory('all',{keepSearch:true});});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus();}});
function route(){const id=location.hash.startsWith('#shelf=')?location.hash.slice(7):'home';openCategory(id,{fromHash:true});}window.addEventListener('popstate',route);window.addEventListener('storage',e=>{if(e.key==='behjat-cart-v1'||e.key==='behjat-favorites-v1'){cart=sanitizeCart(read('behjat-cart-v1',{}));const f=read('behjat-favorites-v1',[]);favorites=Array.isArray(f)?f.filter(id=>products.some(p=>p.id===id)):[];updateCart();if(current!=='home')renderShelf();}});
let toastTimer;function toast(message){$('#shop-toast').textContent=message;$('#shop-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#shop-toast').classList.remove('visible'),2700);}
const music=$('#ambient-music');const savedVolume=Number(read('behjat-volume',.35));music.volume=Number.isFinite(savedVolume)?Math.min(1,Math.max(0,savedVolume)):.35;$('#volume').value=Math.round(music.volume*100);function musicState(){const playing=!music.paused;$('.music-control').classList.toggle('playing',playing);$('#music-toggle').setAttribute('aria-pressed',playing);$('#music-toggle').setAttribute('aria-label',playing?'توقف موسیقی آرام':'پخش موسیقی آرام');$('#music-label').textContent=playing?'عصرِ آرامِ بهجت':'کمی آرامش؟';}$('#music-toggle').addEventListener('click',async()=>{try{if(music.paused)await music.play();else music.pause();musicState();}catch{toast('موسیقی هنوز بارگذاری نشده؛ دوباره امتحان کن.');}});music.addEventListener('play',musicState);music.addEventListener('pause',musicState);music.addEventListener('error',()=>{musicState();});$('#volume').addEventListener('input',e=>{music.volume=Number(e.target.value)/100;try{localStorage.setItem('behjat-volume',JSON.stringify(music.volume));}catch{}});
recommend();updateCart();route();
if(document.modelContext?.registerTool){const tools=[{name:'view_stationery_shelf',title:'باز کردن قفسه',description:'Navigate to a stationery shelf. Does not add products or place orders.',inputSchema:{type:'object',properties:{category:{type:'string',enum:categories.map(c=>c.id).concat(['all','favorites'])}},required:['category'],additionalProperties:false},execute(input){if(!input||!categories.some(c=>c.id===input.category)&&!['all','favorites'].includes(input.category)||Object.keys(input).some(k=>k!=='category'))throw Error('Invalid category');openCategory(input.category);return{category:current};}},{name:'read_local_cart',title:'مشاهدهٔ سبد محلی',description:'Read this device’s demo cart. Prices are illustrative; no order or payment exists.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute(){return{items:Object.entries(cart).map(([id,quantity])=>({id,quantity,name:products.find(p=>p.id===id).name})),...cartTotals(cart),demo:true};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool({...tool,annotations:{readOnlyHint:tool.name==='read_local_cart',untrustedContentHint:false}})).catch(console.warn);}catch(e){console.warn(e);}}}
